package com.northstarbank.console.data;import java.time.LocalDate;import java.util.*;import org.apache.ibatis.annotations.*;
@Mapper public interface TransactionSortMapper{@Select("SELECT id,account_number,customer_id,branch,booking_date,amount,currency,description,channel,reference FROM transaction_search WHERE customer_id=#{customerId} AND booking_date BETWEEN #{from} AND #{to} ORDER BY ${sortColumn} ${direction} LIMIT 200")List<TransactionRow> sorted(@Param("customerId")String customerId,@Param("from")LocalDate from,@Param("to")LocalDate to,@Param("sortColumn")String trustedSortColumn,@Param("direction")String trustedDirection);}
